+bool
+proto_is_bytes_pino(const protocol_t *protocol)
+{
+	header_field_info *hfinfo;
+
+	if (!proto_is_pino(protocol))
+		return false;
+
+	PROTO_REGISTRAR_GET_NTH(protocol->proto_id, hfinfo);
+	return hfinfo->type != FT_PROTOCOL;
+}
